import assert from 'node:assert/strict';
import { createController } from './src/controller.js';

const deferred = () => {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
};

{
  const jobs = [];
  const records = [], renders = [];
  const controller = createController({
    service: { commit(snapshot) { const job = deferred(); jobs.push({ snapshot, job }); return job.promise; } },
    audit: { record(entry) { records.push(entry); } },
    render: state => renders.push(state)
  });
  assert.equal(controller.submit(), null);
  controller.open('one', 'ada');
  controller.edit('first');
  const pending = controller.submit();
  assert.ok(pending instanceof Promise);
  controller.edit('later');
  assert.deepEqual(jobs[0].snapshot, { doc: 'one', actor: 'ada', text: 'first' });
  assert.deepEqual(renders, []);
  jobs[0].job.resolve({ revision: 7 });
  assert.deepEqual(await pending, { revision: 7 });
  assert.deepEqual(records, [{ doc: 'one', actor: 'ada', text: 'first', revision: 7 }]);
  assert.deepEqual(renders, [{ status: 'saved', doc: 'one' }]);
}

{
  const jobs = [];
  const records = [], renders = [];
  const controller = createController({
    service: { commit() { const job = deferred(); jobs.push(job); return job.promise; } },
    audit: { record(entry) { records.push(entry); } },
    render: state => renders.push(state)
  });
  controller.open('one', 'ada');
  const old = controller.submit();
  const latest = controller.submit();
  jobs[0].resolve({ revision: 1 });
  jobs[1].reject(new Error('offline'));
  assert.deepEqual(await old, { revision: 1 });
  assert.equal(await latest, undefined);
  assert.deepEqual(records, [{ doc: 'one', actor: 'ada', text: '', revision: 1 }]);
  assert.deepEqual(renders, [{ status: 'error', doc: 'one' }]);
}

{
  const job = deferred();
  const records = [], renders = [];
  const controller = createController({
    service: { commit() { return job.promise; } },
    audit: { record(entry) { records.push(entry); } },
    render: state => renders.push(state)
  });
  controller.open('old', 'ada');
  const pending = controller.submit();
  controller.close();
  controller.open('new', 'bea');
  job.resolve({ revision: 2 });
  await pending;
  assert.deepEqual(records, [{ doc: 'old', actor: 'ada', text: '', revision: 2 }]);
  assert.deepEqual(renders, []);
}

